enum LotStatus { RECEIVED, TESTING, PASSED, FAILED, APPROVED }

record Material(String code, String name) {}

record Lot(String lotNo, Material material, LocalDate receivedOn,
           LocalDate expiresOn, LotStatus status) {

    Lot {   // コンパクトコンストラクタで入力チェック
        Objects.requireNonNull(lotNo);
        if (expiresOn.isBefore(receivedOn))
            throw new IllegalArgumentException("有効期限が受入日より前です");
    }

    Lot withStatus(LotStatus next) {   // record は不変なので新しいインスタンスを返す
        return new Lot(lotNo, material, receivedOn, expiresOn, next);
    }
}
